No codebase given, so here's a vanilla JS example:

```html
<button class="delete-btn" data-id="123">Delete</button>

<dialog id="confirmModal" open>
  <p>Are you sure? This cannot be undone.</p>
  <button id="confirmDelete">Delete</button>
  <button onclick="confirmModal.close()">Cancel</button>
</dialog>

<script>
const modal = document.getElementById('confirmModal');
let itemToDelete = null;

document.addEventListener('click', (e) => {
  if (e.target.classList.contains('delete-btn')) {
    itemToDelete = e.target.dataset.id;
    modal.showModal();
  }
});

document.getElementById('confirmDelete').addEventListener('click', () => {
  fetch(`/api/items/${itemToDelete}`, { method: 'DELETE' })
    .then(() => { /* remove from DOM */ })
    .catch(err => console.error(err));
  modal.close();
});
</script>

<style>
dialog::backdrop { background: rgba(0,0,0,0.5); }
dialog { border: 1px solid #ccc; border-radius: 8px; padding: 20px; }
</style>
```

**For React:** swap the event listener for `onClick={handleDelete}` → `setItemId()` → `setShowModal(true)`, then render `<dialog open={showModal}>`.

**For Bootstrap/UI lib:** use their modal component instead of `<dialog>`.

